import 'package:flutter/material.dart';import 'package:model_viewer_plus/model_viewer_plus.dart';class Screen3D extends StatelessWidget {  const Screen3D({super.key});  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(title: const Text('Model Viewer')),      body: ModelViewer(        src: 'Assets/3d/uploads_files_4884024_chair.glb',        alt: 'A 3D model of a modern sofa',        ar: true,        // AR support        arModes: ['scene-viewer', 'webxr', 'quick-look'],        // أوضاع AR        cameraControls: true,        // Allow the user to rotate and move the camera        disableZoom: false,        // Allow zooming and miniaturization        autoRotate: true,        //Rotate the form automatically        rotationPerSecond: "30deg",        // Spinning        cameraOrbit: "0deg 75deg 2.5m",        //Camera settings        shadowIntensity: 1.0,        // The severity of the shadows        shadowSoftness: 0.5,        //The softness of shades        exposure: 1.5, // Improving lighting      ),    );  }}